1	"use client";
2	
3	import { useActionState, useEffect, useMemo, useRef, useState } from "react";
4	import { Icon, Plate, AppIcon } from "./Icon";
5	import { Band, Pick, PlanCard, RegionCard, AddonRow, SvcIcon, StepMarks, DiskMeter, Fold, IntroRenewalNote } from "./OrderBits";
6	import { Flag } from "./Bits";
7	import { RegionGlobe } from "./RegionGlobe";
8	import { useRegionLatency } from "./useRegionLatency";
9	import { PlayLockup } from "./GlobeBg";
10	import { OrderProvider, useOrder, type Catalog } from "./order";
11	import { payAndDeployGame } from "@/lib/actions-gameplans";
12	import { submitHosting, submitEmail } from "@/lib/nx/submit-hosting";
13	import { purchaseDomain } from "@/lib/actions-domains";
14	import { searchDomains, type DomainResult } from "@/lib/nx/search-domains";
15	import { SERVICE_TILES } from "@/lib/nx/catalog";
16	import { useMoney } from "./useMoney";
17	import { AddressAutocompleteInput } from "@/components/customer/AddressAutocompleteInput";
18	import { PhoneCountryInput } from "@/components/customer/PhoneCountryInput";
19	import { REG_COUNTRIES } from "@/lib/nx/countries";
20	import type { GameFamilyOption, OsOption, TermOption } from "./order-types";
21	import { GENRE_ORDER } from "@/lib/games";
22	import { payAndDeploy } from "@/lib/actions";
23	import { NxCardFields } from "./NxCardFields";
24	import { PayPalScriptProvider, PayPalButtons, FUNDING } from "@paypal/react-paypal-js";
25	import { PayPalNeonLogo } from "./PayPalNeonLogo";
26	import { openWizardPayPalOrder } from "@/lib/nx/paypal-order";
27	import { captureExternalPayPalOrder } from "@/lib/actions-payment-providers";
28	import { checkGameSubdomain } from "@/lib/actions-subdomain-check";
29	import { checkHostingSubdomain } from "@/lib/actions-hosting";
30	import { trackDeployStep, trackDeployError, type DeployProduct } from "@/lib/deploy-funnel-client";
31	import { ExitIntentModal } from "./ExitIntentModal";
32	
33	/** The four products the deploy funnel actually tracks (lib/deploy-funnel.ts's
34	 *  `PRODUCTS`). Domains are a separate flow with no funnel of its own. */
35	function funnelProduct(service: string | null): DeployProduct | null {
36	  return service === "vps" || service === "game" || service === "hosting" || service === "email"
37	    ? service
38	    : null;
39	}
40	
41	/** The game picker's reset chip. Not a genre, so it is not in GENRE_ORDER. */
42	const ALL_GAMES = "All games";
43	
44	/** Largest player count any of this family's sellable tiers provides. */
45	function maxSlots(g: GameFamilyOption): number | null {
46	  const counts = g.tiers.map((t) => t.slots).filter((n): n is number => typeof n === "number" && n > 0);
47	  return counts.length ? Math.max(...counts) : null;
48	}
49	
50	/* One game-picker card. Split out from an inline `.map()` body so each tile
51	 * can hold its OWN "did the image actually load" state — `onError` hiding a
52	 * failed <img> is the same convention already used for this same hero art in
53	 * GameHero.tsx (customer + marketing) and GameCoverTile's poster chain; the
54	 * wizard's grid was the one surface still rendering a bare <img src={g.art}>
55	 * with nothing to catch a 404 (kf2 has cover art but no hero shot yet — that
56	 * shows here as a broken-image glyph instead of the service-mark fallback
57	 * every OTHER artless family already gets). */
58	function GameTile({ g, on, onClick }: { g: GameFamilyOption; on: boolean; onClick: () => void }) {
59	  const money = useMoney();
60	  const [imgOk, setImgOk] = useState(true);
61	  const showArt = g.art && imgOk;
62	  return (
63	    <Pick on={on} onClick={onClick} className="group flex flex-col gap-1.5 p-1.5">
64	      <span className="relative block aspect-[4/3] w-full overflow-hidden rounded-[7px]">
65	        {g.popular && (
66	          /* Solid, not the translucent-tint treatment "First month free" uses
67	             elsewhere — that one sits on a plain dark card, this one sits on
68	             top of an arbitrary, often bright game screenshot. A ~16%-alpha
69	             mint tint over a busy photo has no reliable contrast against it;
70	             a near-opaque dark chip does, regardless of what's underneath. */
71	          <span className="absolute left-1.5 top-1.5 z-[1] rounded-full border border-[rgba(17,200,142,0.5)]
72	                           bg-[#04140f]/90 px-1.5 py-[2px] text-[9px] font-bold uppercase
73	                           tracking-[0.03em] text-mint">
74	            Popular
75	          </span>
76	        )}
77	        {showArt ? (
78	          <img src={g.art!} alt="" loading="lazy" draggable={false} onError={() => setImgOk(false)}
79	               className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.07]"
