192	function DeckWithCheck({ service, steps, i, children }: {
193	  service: string | null; steps: number; i: number; children: React.ReactNode[];
194	}) {
195	  if (service && children.length !== steps) {
196	    // eslint-disable-next-line no-console
197	    console.error(
198	      `[deploy] slide/step mismatch for "${service}": ${children.length} slides for ${steps} steps — ` +
199	      "the deck is indexed positionally, so every step after the difference shows the wrong screen."
200	    );
