205	function Deck({ i, steps, children }: { i: number; steps: number; children: React.ReactNode[] }) {
206	  const track = useRef<HTMLDivElement>(null);
207	  const [h, setH] = useState<number | undefined>(undefined);
208	
209	  /* The deck is indexed POSITIONALLY against the step list, but the two are
210	     built by separate sets of conditionals — so a product whose slides and
211	     steps disagree silently renders the wrong screen. That is exactly how
212	     hosting, email and domains ended up walking the VPS flow: the VPS plan
213	     slide was skipped for `game` only, so for the other three the deck had one
214	     slide too many and every index landed one place early.
215	     A mismatch is a bug, and in development it should be loud rather than
216	     something a customer discovers. */
217	
218	
219	  useEffect(() => {
220	    const el = track.current?.children[i] as HTMLElement | undefined;
221	    if (!el) return;
222	    const measure = () => setH(el.offsetHeight);
223	    measure();
224	    const ro = new ResizeObserver(measure);
225	    ro.observe(el);
226	    return () => ro.disconnect();
227	  }, [i, children.length]);
228	
229	  return (
230	    <div className="deck overflow-hidden transition-[height] duration-[420ms] ease-[cubic-bezier(.4,0,.2,1)]"
231	         style={{ height: h }}>
232	      <div ref={track}
233	           className="deck-track flex items-start transition-transform duration-[420ms] ease-[cubic-bezier(.4,0,.2,1)]"
234	           style={{ transform: `translateX(-${i * 100}%)` }}>
235	        {children.map((c, n) => (
236	          <div key={n} aria-hidden={n !== i} inert={n !== i} className="w-full shrink-0 px-[2px]">{c}</div>
237	        ))}
238	      </div>
239	    </div>
240	  );
241	}
