505	/* ── payment slide — the only place an order can be placed ─────────────── */
506	function PaymentSlide({ methods, paypalClientId, active, onEdit }: {
507	  methods: { card: boolean; paypal: boolean; crypto: boolean };
508	  /* PayPal's PUBLIC client id — safe in the browser, it is what the SDK script
509	     is keyed on. Null when PayPal is not configured for this environment. */
510	  paypalClientId: string | null;
511	  /** True only while this is the step on screen. */
512	  active: boolean;
513	  onEdit: () => void;
514	}) {
515	  const { o, set, price, pricing, priceError, cat, walletApplied, cardDue, plan, game, sections, hostCheck } = useOrder();
516	  const money = useMoney();
517	  const isGame = o.service === "game";
518	  const isHosting = o.service === "hosting";
519	  const isEmail = o.service === "email";
520	  const isDomains = o.service === "domains";
521	  const c = o.contact;
522	  const ready =
523	    isGame ? !!o.gamePlanId && o.serverName.trim().length > 1 && (!game?.needsSubdomain || o.subdomain.trim().length > 2)
524	    /* A hosting order needs only a PLAN. Both name fields are optional: with
525	       neither, `placeHostingOrder` issues a free `<username>.<base>` subdomain —
526	       "Empty/omitted => a free subdomain", in its own words. Requiring one here
527	       meant the server would happily take an order the button refused to send,
528	       and the customer saw a live card form above a dead button. */
