import type { ConfigField } from "@/lib/game-config";

export type PlanOption = {
  id: string;
  slug: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  /** Regular monthly rate, for the struck-through "was" figure. */
  monthlyCents: number;
  /**
   * Effective monthly rate at the CURRENTLY SELECTED term, computed server-side
   * from the same annual-discount basis the charge path uses. Recomputed by the
   * server when the term changes — never derived here.
   */
  effectiveMonthlyCents: number;
  /** Set when the plan carries an intro rate, so the copy can be honest:
   *  the card headlines `introMonthlyCents` and states
   *  `introRenewalMonthlyCents` right under it ("First month, then $X/mo").
   *  Both null together, via lib/intro-pricing.ts's planIntroMonthlyCents. */
  introMonthlyCents: number | null;
  introRenewalMonthlyCents: number | null;
  recommended?: boolean;
};

export type OsOption = {
  id: string;
  name: string;
  version: string;
  /** Icon key in the interface sprite sheet. */
  icon: string;
  /** Which tab it belongs under in the Server settings panel. */
  category: "PLAIN_OS" | "CONTROL_PANEL" | "APPLICATION";
  /**
   * `ubuntu` | `debian` | `almalinux` | `rocky` | ... — the platform's own
   * grouping key. Each OsTemplate row is ONE VERSION; the design shows a card
   * per family with its versions as chips underneath, which is exactly what
   * this field already expresses.
   */
  family: string;
  /**
   * Key into the third-party mark sheet, when one exists. Control panels and
   * applications have their own drawn marks; the interface icon set has no
   * cPanel or WordPress glyph, so without this every one of them renders as the
   * same generic cube. Null for plain OS, which uses the interface set.
   */
  spriteKey: string | null;
};

