/* ── game ─────────────────────────────────────────────────────────────────
   A family is what the customer picks; a TIER is what they buy. Each GamePlan
   row is one tier of one family, so the picker is two levels and the money only
   attaches at the second. */

export type GameTier = {
  id: string;
  name: string;
  ramMB: number;
  cpuCores: number;
