  /** Same intro-rate shape as `PlanOption` — null on a tier with no intro price. */
  introMonthlyCents: number | null;
  introRenewalMonthlyCents: number | null;
};

export type GameFamilyOption = {
  family: string;
  name: string;
  /** Artwork path, or null when the family has none (card falls back). */
  art: string | null;
