24	export function StatCard({
25	  label,
26	  value,
27	  delta,
28	  deltaGood,
29	  spark,
30	  sparkColor = "#8a70fb",
31	  icon,
32	  href,
33	}: {
34	  label: string;
35	  value: string;
36	  delta?: string;
37	  deltaGood?: boolean;
38	  spark?: number[];
39	  sparkColor?: string;
40	  icon?: React.ReactNode;
41	  href?: string;
42	}) {
43	  const inner = (
44	    <div className="card card-hover flex h-full flex-col justify-between p-5">
45	      <div className="flex items-start justify-between">
46	        <div>
47	          <p className="text-[13px] text-slate-400">{label}</p>
48	          <p className="mt-1.5 text-2xl font-bold tracking-tight">{value}</p>
49	          {delta && (
50	            <p className={`mt-1 text-xs font-medium ${deltaGood === false ? "text-red-400" : "text-emerald-400"}`}>
51	              {delta}
52	            </p>
53	          )}
54	        </div>
55	        {icon && (
56	          <div className="rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-2.5 text-brand-300">
