133	  title,
134	  sub,
135	  action,
136	}: {
137	  title: string;
138	  sub?: string;
139	  action?: React.ReactNode;
140	}) {
141	  return (
142	    <div className="card flex flex-col items-center justify-center py-14 text-center">
143	      <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
144	        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.5">
145	          <rect x="3" y="5" width="18" height="6" rx="2" />
146	          <rect x="3" y="13" width="18" height="6" rx="2" />
147	          <circle cx="7" cy="8" r="0.5" fill="#8a70fb" />
148	          <circle cx="7" cy="16" r="0.5" fill="#8a70fb" />
149	        </svg>
150	      </div>
151	      <h3 className="text-base font-semibold">{title}</h3>
152	      {sub && <p className="mt-1 max-w-sm text-sm text-slate-400">{sub}</p>}
153	      {action && <div className="mt-5">{action}</div>}
154	    </div>
155	  );
156	}
157	
158	export function ComingSoon({ feature, note }: { feature: string; note?: string }) {
159	  return (
160	    <div className="card border-dashed py-12 text-center">

190	      {centerSub && (
191	        <text x="50%" y="62%" textAnchor="middle" fontSize="10" fill="#64748b">
192	          {centerSub}
193	        </text>
194	      )}
195	    </svg>
196	  );
197	}
198	
199	export function MeterBar({
200	  value,
201	  max,
202	  color = "#6f47f5",
203	  className = "",
204	}: {
205	  value: number;
206	  max: number;
207	  color?: string;
208	  className?: string;
209	}) {
210	  const pct = Math.min(100, (value / (max || 1)) * 100);
211	  return (
