import { db } from "@/lib/db";
import { GAME_DISPLAY } from "@/lib/games";
import { REGION_LABELS } from "@/lib/node-regions";
import type { SelectionTally } from "@/lib/deploy-funnel";

/**
 * Real-order popularity — "what people actually BUY", read straight off the
 * Server / HostingAccount / EmailSubscription tables (the completed-order
 * ground truth: lib/order.ts, lib/game-order.ts, lib/actions-hosting.ts and
 * lib/actions-email-hosting.ts all write these rows on a successful order).
 *
 * This is the trustworthy half of "what's popular." The deploy-wizard
 * `select` events (lib/deploy-funnel.ts's `deploySelections`) capture what a
 * customer CONSIDERED clicking through the wizard — a weaker signal, since a
 * customer can click through every tier before buying the cheapest one. Both
 * are surfaced together on /admin/popularity, via `considerVsBought` below.
 *
 * Free grants (`Server.isFree`) are excluded from every count here — a free
 * or admin-granted server was never chosen AT A PRICE, so counting it as
 * "popular" would be counting a gift, not a purchase.
 */

const DAY = 86_400_000;
export const POPULARITY_WINDOWS = [7, 30, 90] as const;
export type PopularityWindowDays = (typeof POPULARITY_WINDOWS)[number];

export type RankedCount = { key: string; label: string; count: number };

export type PlanPopularity = {
  windowDays: number;
  totals: { vps: number; game: number; hosting: number; email: number };
  topGames: RankedCount[];
  /** gameFamily -> ranked GamePlan tiers bought within that family. */
  topGameTiersByFamily: Record<string, RankedCount[]>;
  topVpsPlans: RankedCount[];
  topHostingPlans: RankedCount[];
  topEmailPlans: RankedCount[];
  /** Server region, vps + game combined (hosting/email have no region). */
  regions: RankedCount[];
  /** Billing term (months), all four products combined. */
  terms: RankedCount[];
};

const TERM_LABEL: Record<number, string> = { 1: "Monthly", 12: "Annual", 24: "2 years", 36: "3 years" };

function bump(map: Map<string, { label: string; count: number }>, key: string, label: string): void {
  const cur = map.get(key);
  if (cur) cur.count += 1;
  else map.set(key, { label, count: 1 });
}

function rank(map: Map<string, { label: string; count: number }>, limit = 10): RankedCount[] {
  return [...map.entries()]
    .map(([key, v]) => ({ key, label: v.label, count: v.count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Build the real-order popularity view over the trailing `days` window. */
export async function realOrderPopularity(days: PopularityWindowDays = 30): Promise<PlanPopularity> {
  const since = new Date(Date.now() - days * DAY);

  const [servers, hostingAccounts, emailSubs] = await Promise.all([
    db.server.findMany({
      where: { createdAt: { gte: since }, isFree: false },
      select: {
        planId: true,
        gamePlanId: true,
        region: true,
        termMonths: true,
        plan: { select: { name: true, active: true } },
        gamePlan: { select: { gameFamily: true, name: true } },
      },
      take: 20_000,
    }),
    db.hostingAccount.findMany({
      where: { createdAt: { gte: since } },
      select: { termMonths: true, plan: { select: { id: true, name: true } } },
      take: 20_000,
    }),
    db.emailSubscription.findMany({
      where: { createdAt: { gte: since } },
      select: { termMonths: true, emailPlan: { select: { id: true, name: true } } },
      take: 20_000,
    }),
  ]);

  const games = new Map<string, { label: string; count: number }>();
  const gameTiersByFamily = new Map<string, Map<string, { label: string; count: number }>>();
  const vpsPlans = new Map<string, { label: string; count: number }>();
  const regions = new Map<string, { label: string; count: number }>();
  const terms = new Map<string, { label: string; count: number }>();

  let vpsCount = 0;
  let gameCount = 0;

  for (const s of servers) {
    // Region + term apply to every Server row — VPS and game alike.
    bump(regions, s.region, REGION_LABELS[s.region] ?? s.region);
    bump(terms, String(s.termMonths), TERM_LABEL[s.termMonths] ?? `${s.termMonths} mo`);

    if (s.gamePlanId && s.gamePlan) {
      gameCount += 1;
      const familyLabel = (GAME_DISPLAY as Record<string, { name: string } | undefined>)[s.gamePlan.gameFamily]?.name
        ?? s.gamePlan.gameFamily;
      bump(games, s.gamePlan.gameFamily, familyLabel);
      const tiers = gameTiersByFamily.get(s.gamePlan.gameFamily) ?? new Map<string, { label: string; count: number }>();
      bump(tiers, s.gamePlanId, s.gamePlan.name);
      gameTiersByFamily.set(s.gamePlan.gameFamily, tiers);
    } else if (s.plan.active) {
      // NxCloud's backing Plan is deliberately kept `active = false` so it
      // never shows in the VPS wizard (see the NxCloudPlan schema comment) —
      // excluding inactive plans here keeps NxCloud VMs out of "VPS plan
      // popularity" without a direct NxCloudInstance join.
      vpsCount += 1;
      bump(vpsPlans, s.planId, s.plan.name);
    }
  }

  const hostingPlans = new Map<string, { label: string; count: number }>();
  for (const h of hostingAccounts) {
    bump(hostingPlans, h.plan.id, h.plan.name);
    bump(terms, String(h.termMonths), TERM_LABEL[h.termMonths] ?? `${h.termMonths} mo`);
  }

  const emailPlans = new Map<string, { label: string; count: number }>();
  for (const e of emailSubs) {
    bump(emailPlans, e.emailPlan.id, e.emailPlan.name);
    bump(terms, String(e.termMonths), TERM_LABEL[e.termMonths] ?? `${e.termMonths} mo`);
  }

  const topGameTiersByFamily: Record<string, RankedCount[]> = {};
  for (const [family, tiers] of gameTiersByFamily) topGameTiersByFamily[family] = rank(tiers);

  return {
    windowDays: days,
    totals: { vps: vpsCount, game: gameCount, hosting: hostingAccounts.length, email: emailSubs.length },
    topGames: rank(games),
    topGameTiersByFamily,
    topVpsPlans: rank(vpsPlans),
    topHostingPlans: rank(hostingPlans),
    topEmailPlans: rank(emailPlans),
    regions: rank(regions, 8),
    terms: rank(terms, 4),
  };
}

/**
 * "Most viewed but least bought" — lines wizard SELECTION tallies (what a
 * customer clicked/considered) up against REAL orders (what they actually
 * paid for) for the same key (a game family slug, a plan id, a term in
 * months, a region key). Both halves come straight off the DB — never
 * fabricated — so where there's no selection data yet (a fresh feature) or no
 * order data yet, that row is simply absent rather than guessed at.
 */
export type ConsiderVsBought = {
  key: string;
  label: string;
  selected: number;
  bought: number;
  /** selected / max(bought,1) — higher means "considered a lot more than bought". */
  ratio: number;
};

export function considerVsBought(selections: SelectionTally[], bought: RankedCount[], limit = 8): ConsiderVsBought[] {
  if (selections.length === 0) return [];
  const boughtByKey = new Map(bought.map((b) => [b.key, b]));
  return selections
    .map((s) => {
      const b = boughtByKey.get(s.value);
      return {
        key: s.value,
        label: b?.label ?? s.value,
        selected: s.count,
        bought: b?.count ?? 0,
        ratio: s.count / Math.max(1, b?.count ?? 0),
      };
    })
    .sort((a, b) => b.ratio - a.ratio || b.selected - a.selected)
    .slice(0, limit);
}

