import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader, StatCard, Badge, EmptyState } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import {
  realOrderPopularity,
  considerVsBought,
  POPULARITY_WINDOWS,
  type RankedCount,
  type PopularityWindowDays,
  type ConsiderVsBought,
} from "@/lib/plan-popularity";
import { deploySelections, mergeSelectionTallies } from "@/lib/deploy-funnel";

export const dynamic = "force-dynamic";

type Win = PopularityWindowDays;

/**
 * Owner request (2026-09-27): "track deploy wizard for what games, plans
 * people are selecting to see what the most popular options are." Two
 * signals, both real, side by side:
 *  - REAL ORDERS (`lib/plan-popularity.ts`'s `realOrderPopularity`) — the
 *    ground truth, off Server/HostingAccount/EmailSubscription.
 *  - WIZARD SELECTIONS (`lib/deploy-funnel.ts`'s `deploySelections`) — what a
 *    customer clicked/considered, whether or not they finished checking out.
 * The "clicked vs bought" tables below exist because the two can disagree in
 * an interesting way — e.g. everyone clicks the biggest tier, most people buy
 * the cheapest one — and that gap is only visible with both numbers present.
 */

function RankedList({ items, color }: { items: RankedCount[]; color?: string }) {
  if (items.length === 0) {
    return <p className="py-6 text-center text-sm text-slate-500">No orders in this window yet.</p>;
  }
  const max = Math.max(...items.map((i) => i.count), 1);
  return (
    <ul className="space-y-3">
      {items.map((it, i) => (
        <li key={it.key}>
          <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
            <span className="min-w-0 truncate font-medium">
              {i + 1}. {it.label}
            </span>
            <span className="shrink-0 tabular-nums text-slate-300">{it.count.toLocaleString()}</span>
          </div>
          <MeterBar value={it.count} max={max} color={color} />
        </li>
      ))}
    </ul>
  );
}

function ConsiderSection({ title, sub, rows }: { title: string; sub: string; rows: ConsiderVsBought[] }) {
  return (
    <div className="card">
      <h2 className="font-semibold">{title}</h2>
      <p className="mt-1 text-xs text-slate-500">{sub}</p>
      {rows.length === 0 ? (
        <p className="py-6 text-center text-sm text-slate-500">
          No wizard-selection data yet — this fills in as customers use the deploy wizard going forward.
        </p>
      ) : (
        <div className="mt-4 overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-slate-500">
                <th className="pb-2 pr-3 font-medium">Item</th>
                <th className="pb-2 pr-3 text-right font-medium">Clicked</th>
                <th className="pb-2 pr-3 text-right font-medium">Bought</th>
                <th className="pb-2 text-right font-medium">Ratio</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.key} className="border-t border-white/[0.06]">
                  <td className="max-w-[220px] truncate py-2 pr-3">{r.label}</td>
                  <td className="py-2 pr-3 text-right tabular-nums text-slate-300">{r.selected.toLocaleString()}</td>
                  <td className="py-2 pr-3 text-right tabular-nums text-slate-300">{r.bought.toLocaleString()}</td>
                  <td className="py-2 text-right">
                    <Badge tone={r.bought === 0 ? "red" : r.ratio >= 3 ? "amber" : "slate"}>{r.ratio.toFixed(1)}×</Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export default async function PopularityPage({
  searchParams,
}: {
  searchParams: Promise<{ days?: string }>;
}) {
  await requireArea("analytics");

  const sp = await searchParams;
  const days: Win = POPULARITY_WINDOWS.includes(Number(sp.days) as Win) ? (Number(sp.days) as Win) : 30;

  const [pop, selections] = await Promise.all([realOrderPopularity(days), deploySelections(days)]);

  const gameVsBought = considerVsBought(mergeSelectionTallies(selections, ["game"], "game"), pop.topGames);
  const vpsPlanVsBought = considerVsBought(mergeSelectionTallies(selections, ["vps"], "plan"), pop.topVpsPlans);
  const gameTierVsBought = considerVsBought(
    mergeSelectionTallies(selections, ["game"], "plan"),
    Object.values(pop.topGameTiersByFamily).flat(),
  );
  const hostingVsBought = considerVsBought(mergeSelectionTallies(selections, ["hosting"], "plan"), pop.topHostingPlans);
  const emailVsBought = considerVsBought(mergeSelectionTallies(selections, ["email"], "plan"), pop.topEmailPlans);

  const totalOrders = pop.totals.vps + pop.totals.game + pop.totals.hosting + pop.totals.email;
  const topFamilies = pop.topGames.slice(0, 6);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Popularity"
        sub="What people actually BUY (real orders), and — where it's interesting — how that compares to what they click through the wizard first."
      >
        <Link href="/admin/deploy-funnel" className="text-sm font-medium text-brand-300 hover:text-brand-200">
          ← Deploy funnel
        </Link>
      </PageHeader>

      <div className="flex gap-2">
        {POPULARITY_WINDOWS.map((w) => (
          <Link
            key={w}
            href={`/admin/popularity?days=${w}`}
            className={`rounded-lg border px-3 py-1.5 text-sm ${
              w === days
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/[0.08] text-slate-400 hover:text-slate-200"
            }`}
          >
            {w}d
          </Link>
        ))}
      </div>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatCard label="VPS orders" value={pop.totals.vps.toLocaleString()} delta={`${days}d · real orders`} />
        <StatCard label="Game orders" value={pop.totals.game.toLocaleString()} delta={`${days}d · real orders`} />
        <StatCard label="Hosting orders" value={pop.totals.hosting.toLocaleString()} delta={`${days}d · real orders`} />
        <StatCard label="Email orders" value={pop.totals.email.toLocaleString()} delta={`${days}d · real orders`} />
      </div>

      {totalOrders === 0 ? (
        <EmptyState
          title="No completed orders in this window"
          sub="Real orders (Server / HostingAccount / EmailSubscription rows) show up here the moment a checkout succeeds."
        />
      ) : (
        <div className="grid gap-4 lg:grid-cols-2">
          <div className="card">
            <h2 className="font-semibold">Most popular games</h2>
            <p className="mt-1 text-xs text-slate-500">Real Server orders, by game family.</p>
            <div className="mt-4">
              <RankedList items={pop.topGames} color="#22c55e" />
            </div>
          </div>
          <div className="card">
            <h2 className="font-semibold">Most popular VPS plans</h2>
            <p className="mt-1 text-xs text-slate-500">Real Server orders. Free servers and NxCloud VMs excluded.</p>
            <div className="mt-4">
              <RankedList items={pop.topVpsPlans} color="#3b82f6" />
            </div>
          </div>
          <div className="card">
            <h2 className="font-semibold">Most popular web hosting plans</h2>
            <p className="mt-1 text-xs text-slate-500">Real HostingAccount orders.</p>
            <div className="mt-4">
              <RankedList items={pop.topHostingPlans} color="#f59e0b" />
            </div>
          </div>
          <div className="card">
            <h2 className="font-semibold">Most popular email plans</h2>
            <p className="mt-1 text-xs text-slate-500">Real EmailSubscription orders.</p>
            <div className="mt-4">
              <RankedList items={pop.topEmailPlans} color="#ec4899" />
            </div>
          </div>
          <div className="card">
            <h2 className="font-semibold">Region</h2>
            <p className="mt-1 text-xs text-slate-500">VPS + game orders combined. Hosting/email have no region.</p>
            <div className="mt-4">
              <RankedList items={pop.regions} color="#06b6d4" />
            </div>
          </div>
          <div className="card">
            <h2 className="font-semibold">Billing term</h2>
            <p className="mt-1 text-xs text-slate-500">All four products combined.</p>
            <div className="mt-4">
              <RankedList items={pop.terms} color="#a855f7" />
            </div>
          </div>
        </div>
      )}

      {topFamilies.length > 0 && (
        <div className="card">
          <h2 className="font-semibold">Most popular tiers, per game</h2>
          <p className="mt-1 text-xs text-slate-500">Real GamePlan orders within each of the top families.</p>
          <div className="mt-4 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {topFamilies.map((g) => (
              <div key={g.key}>
                <h3 className="mb-2 text-sm font-semibold text-slate-200">{g.label}</h3>
                <RankedList items={pop.topGameTiersByFamily[g.key] ?? []} color="#22c55e" />
              </div>
            ))}
          </div>
        </div>
      )}

      <ConsiderSection
        title="Games: clicked vs bought"
        sub="A game family far ahead on clicks but behind on orders is a real signal — not fabricated, both numbers come off the DB."
        rows={gameVsBought}
      />
      <ConsiderSection
        title="VPS plans: clicked vs bought"
        sub="e.g. everyone clicks the biggest plan but buys the smallest — this is where that would show up."
        rows={vpsPlanVsBought}
      />
      <ConsiderSection title="Game tiers: clicked vs bought" sub="Across every family." rows={gameTierVsBought} />
      <ConsiderSection title="Hosting plans: clicked vs bought" sub="" rows={hostingVsBought} />
      <ConsiderSection title="Email plans: clicked vs bought" sub="" rows={emailVsBought} />
    </div>
  );
}

